void setup() {
  pinMode(2, INPUT);
  pinMode(13, OUTPUT);
  Serial.begin(9600);
}
void loop() {
  static int last = HIGH;
  int cur = digitalRead(2);
  if (cur != last) {
    delay(50);
    if (digitalRead(2) == cur) {
      last = cur;
      digitalWrite(13, !digitalRead(13));
      Serial.println(cur == LOW ? "Pressed" : "Released");
    }
}
}

