#include <Wire.h>
#include <LiquidCrystal_I2C.h>

LiquidCrystal_I2C lcd(0x27, 16, 2);

#define trigPin 9
#define echoPin 10

const float EMPTY_DISTANCE = 400.0;
const float FULL_DISTANCE  = 0.0;

void setup() {
  Serial.begin(9600);

  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);

  lcd.init();
  lcd.backlight();

  lcd.setCursor(0, 0);
  lcd.print("WATER LEVEL");
  lcd.setCursor(0, 1);
  lcd.print("Initializing");
  delay(2000);

  lcd.clear();
}

void loop() {
  long duration;
  float distance;
  float fillLevel;
  String status;

  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);

  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);

  digitalWrite(trigPin, LOW);

  duration = pulseIn(echoPin, HIGH);

  distance = duration * 0.0343 / 2.0;

  if (distance < 0) distance = 0;
  if (distance > 400) distance = 400;

  fillLevel = ((EMPTY_DISTANCE - distance) * 100.0) /
              (EMPTY_DISTANCE - FULL_DISTANCE);

  fillLevel = constrain(fillLevel, 0, 100);

  if (fillLevel >= 90) {
    status = "FULL";
  }
  else if (fillLevel >= 70) {
    status = "HIGH";
  }
  else if (fillLevel >= 40) {
    status = "MEDIUM";
  }
  else if (fillLevel >= 10) {
    status = "LOW";
  }
  else {
    status = "EMPTY";
  }

  Serial.print("Distance: ");
  Serial.print(distance);
  Serial.print(" cm   ");

  Serial.print("Fill: ");
  Serial.print(fillLevel);
  Serial.print("%   ");

  Serial.print("Status: ");
  Serial.println(status);

  lcd.setCursor(0, 0);
  lcd.print("Fill:");
  lcd.print((int)fillLevel);
  lcd.print("%   ");

  lcd.setCursor(0, 1);
  lcd.print("Status:");
  lcd.print(status);
  lcd.print("    ");

  delay(1000);
}

