void setup() {
  myservo.attach(11);
  pinMode(trig,OUTPUT);
  pinMode(echo,INPUT);
  pinMode(enA,OUTPUT);
  pinMode(in1,OUTPUT);
  pinMode(in2,OUTPUT);
  pinMode(enB,OUTPUT);
  pinMode(in3,OUTPUT);
  pinMode(in4,OUTPUT);
  Serial.begin(9600);
}
void loop() {
  long dur=pulseIn(echo,HIGH);
  float cm=dur*0.034/2;
  if(cm<30) {
    digitalWrite(in1,LOW);
    digitalWrite(in2,LOW);
    digitalWrite(in3,LOW);
    digitalWrite(in4,LOW);
    myservo.write(90);
    delay(500);
  } else {
  digitalWrite(in1,HIGH);
  digitalWrite(in2,LOW);
  digitalWrite(in3,HIGH);
  digitalWrite(in4,LOW);
  analogWrite(enA,200);
  analogWrite(enB,200);
}
}

