    cmd = Serial.readStringUntil("
");
    cmd.trim();
    if (cmd == "red")        { digitalWrite(9, HIGH); digitalWrite(10, LOW); digitalWrite(11, LOW); }
    else if (cmd == "green") { digitalWrite(9, LOW); digitalWrite(10, HIGH); digitalWrite(11, LOW); }
    else if (cmd == "blue")  { digitalWrite(9, LOW); digitalWrite(10, LOW); digitalWrite(11, HIGH); }
    else if (cmd == "yellow"){ digitalWrite(9, HIGH); digitalWrite(10, HIGH); digitalWrite(11, LOW); }
    else if (cmd == "cyan")  { digitalWrite(9, LOW); digitalWrite(10, HIGH); digitalWrite(11, HIGH); }
    else if (cmd == "magenta"){digitalWrite(9, HIGH); digitalWrite(10, LOW); digitalWrite(11, HIGH); }
    else if (cmd == "white") { digitalWrite(9, HIGH); digitalWrite(10, HIGH); digitalWrite(11, HIGH); }
    else if (cmd == "off")   { digitalWrite(9, LOW); digitalWrite(10, LOW); digitalWrite(11, LOW); }
    else { Serial.println("Unknown color"); }
    Serial.println(cmd);
  }
}
